const HOUR_MS = 60 * 60 * 1000;

// Throttle checks return null to allow a send, or { reason, retryAt } to block it.

function createHourlyLimit({ channel, store, now, maxPerHour }) {
  function keyFor(user, message) {
    const category = message.category || 'general';
    return `${channel}:${user.id}:${category}`;
  }

  function check(user, message, options) {
    if (options.force || message.priority === 'urgent') {
      return null;
    }

    const key = keyFor(user, message);
    const current = now().getTime();
    const recent = (store.get(key) || []).filter(ts => current - ts < HOUR_MS);

    if (recent.length >= maxPerHour) {
      return {
        reason: `${channel} hourly limit reached`,
        retryAt: new Date(recent[0] + HOUR_MS).toISOString()
      };
    }

    return null;
  }

  function record(user, message) {
    const key = keyFor(user, message);
    const records = store.get(key) || [];
    records.push(now().getTime());
    store.set(key, records);
  }

  return { check, record };
}

function requireMarketingOptIn(optInField, audience) {
  return function checkMarketingOptIn(user, message) {
    if (message.category === 'marketing' && !user[optInField]) {
      return {
        reason: `user has not opted into marketing ${audience}`,
        retryAt: null
      };
    }
    return null;
  };
}

module.exports = {
  createHourlyLimit,
  requireMarketingOptIn
};

