const { createChannelNotifier } = require('./channelNotifier');
const { requireMarketingOptIn } = require('./throttle');

function escapeHtml(value) {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function footerFor(user, message, settings) {
  if (message.category === 'transactional' || message.category === 'security') {
    return `Sent to ${user.email} because of recent account activity.`;
  }
  const url = `${settings.unsubscribeBaseUrl}?user=${encodeURIComponent(user.id)}`;
  return `You can unsubscribe at ${url}.`;
}

const emailChannel = {
  channel: 'email',
  transportName: 'email',
  defaultMaxPerHour: 8,

  resolveSettings(options) {
    return {
      from: options.from || 'noreply@example.com',
      replyTo: options.replyTo || 'support@example.com',
      unsubscribeBaseUrl: options.unsubscribeBaseUrl || 'https://example.com/unsubscribe'
    };
  },

  validateUser(user) {
    if (!user.email || !user.email.includes('@')) {
      throw new TypeError('user.email is required for email notifications');
    }
  },

  checkConsent: requireMarketingOptIn('emailOptIn', 'email'),

  format(base, { user, message, settings }) {
    const subjectPrefix = message.category === 'security' ? '[Action Required] ' : '';
    const footer = footerFor(user, message, settings);

    return {
      to: user.email,
      from: settings.from,
      replyTo: settings.replyTo,
      subject: `${subjectPrefix}${base.title}`,
      text: `${base.body}\n\n${footer}`,
      html: `<h1>${escapeHtml(base.title)}</h1><p>${escapeHtml(base.body)}</p><footer>${escapeHtml(footer)}</footer>`,
      preview: base.body.slice(0, 90)
    };
  }
};

function createEmailNotifier(options = {}) {
  return createChannelNotifier(emailChannel, options);
}

module.exports = {
  createEmailNotifier
};
