      assert.equal((await notifier.send(validUsers[channel], message)).status, 'sent');
    }
    assert.deepEqual([...throttleStore.keys()].sort(), [
      'email:u1:general',
      'inapp:u4:general',
      'slack:u3:general',
      'sms:u2:general'
    ]);
  });

  test('send works when detached from the notifier object', async () => {
    const { send } = createNotifier('inapp', { transport: recordingTransport() });
    assert.equal((await send(validUsers.inapp, { title: 'T', body: 'B' })).status, 'sent');
  });
});

describe('shared validation', () => {
  // Run for every channel: a channel check reached with a bad user would throw a different error.
  const userCases = [
    ['missing user', null, /^user is required$/],
    ['non-object user', 'u1', /^user is required$/],
    ['empty user id', { id: '' }, /user\.id is required/]
  ];

  for (const channel of Object.keys(validUsers)) {
    for (const [name, user, expected] of userCases) {
      test(`${channel} rejects ${name}`, async () => {
        const notifier = createNotifier(channel, { transport: recordingTransport() });
        await assert.rejects(() => notifier.send(user, { title: 'T', body: 'B' }), { name: 'TypeError', message: expected });
      });
    }
  }

  const messageCases = [
    ['missing message', null, /^message is required$/],
    ['empty title', { title: '', body: 'B' }, /message\.title and message\.body are required/],
    ['missing body', { title: 'T' }, /message\.title and message\.body are required/]
  ];

  for (const [name, message, expected] of messageCases) {
    test(`rejects ${name}`, async () => {
      const notifier = createNotifier('sms', { transport: recordingTransport() });
      await assert.rejects(() => notifier.send(validUsers.sms, message), { name: 'TypeError', message: expected });
    });
  }

  test('channel user checks run after the shared checks', async () => {
    const checks = [
      ['email', { id: 'u1', email: 'not-an-address' }, /user\.email is required/],
      ['sms', { id: 'u2', phone: '+0123' }, /E\.164/],
      ['slack', { id: 'u3' }, /slackId or user\.slackChannel/],
      ['inapp', { id: 'u4', disabledInApp: true }, /disabled for this user/]
    ];
    for (const [channel, user, expected] of checks) {
      const notifier = createNotifier(channel, { transport: recordingTransport() });
      await assert.rejects(() => notifier.send(user, { title: 'T', body: 'B' }), { name: 'TypeError', message: expected });
      await assert.rejects(() => notifier.send({ email: 'a@b' }, { title: 'T', body: 'B' }), /user\.id is required/);
    }
  });
});

describe('throttling', () => {
  test('hourly limit reports retryAt from the oldest send and resets after an hour', async () => {
    const clock = fixedClock();
    const notifier = createNotifier('email', {
      transport: recordingTransport(),
      maxPerHour: 2,
      now: clock.now
    });
    const message = { title: 'T', body: 'B', category: 'digest' };

    await notifier.send(validUsers.email, message);
    clock.advance(10 * 60 * 1000);
    await notifier.send(validUsers.email, message);
    const blocked = await notifier.send(validUsers.email, message);

    assert.deepEqual(blocked, {
      channel: 'email',
      status: 'throttled',
      reason: 'email hourly limit reached',
      retryAt: '2026-01-02T04:00:00.000Z',
      userId: 'u1'
    });

    clock.advance(HOUR_MS - 10 * 60 * 1000);
    assert.equal((await notifier.send(validUsers.email, message)).status, 'sent');
  });

  test('limits are kept per category', async () => {
    const notifier = createNotifier('sms', { transport: recordingTransport(), maxPerHour: 1, now: fixedClock().now });

    await notifier.send(validUsers.sms, { title: 'T', body: 'B', category: 'billing' });
    assert.equal((await notifier.send(validUsers.sms, { title: 'T', body: 'B', category: 'billing' })).status, 'throttled');
    assert.equal((await notifier.send(validUsers.sms, { title: 'T', body: 'B', category: 'orders' })).status, 'sent');
  });

  test('force and urgent priority bypass the hourly limit', async () => {
    const notifier = createNotifier('sms', { transport: recordingTransport(), maxPerHour: 1, now: fixedClock().now });
    const message = { title: 'T', body: 'B' };

    await notifier.send(validUsers.sms, message);
    assert.equal((await notifier.send(validUsers.sms, message, { force: true })).status, 'sent');
    assert.equal((await notifier.send(validUsers.sms, { ...message, priority: 'urgent' })).status, 'sent');
    assert.equal((await notifier.send(validUsers.sms, message)).status, 'throttled');
  });

  test('marketing consent is required even when the hourly limit is bypassed', async () => {
    const cases = [
      ['email', { id: 'e1', email: 'e@example.com' }, 'user has not opted into marketing email'],
      ['sms', { id: 's1', phone: '+15551234567' }, 'user has not opted into marketing SMS']
    ];
    for (const [channel, user, reason] of cases) {
      const notifier = createNotifier(channel, { transport: recordingTransport() });
      const urgent = await notifier.send(user, { title: 'T', body: 'B', category: 'marketing', priority: 'urgent' });
      const forced = await notifier.send(user, { title: 'T', body: 'B', category: 'marketing' }, { force: true });

      assert.deepEqual(urgent, { channel, status: 'throttled', reason, retryAt: null, userId: user.id });
      assert.equal(forced.reason, reason);
    }
  });

  test('hourly limit is reported before missing marketing consent', async () => {
    const throttleStore = new Map([['email:e1:marketing', [Date.parse(NOW)]]]);
    const notifier = createNotifier('email', { transport: recordingTransport(), throttleStore, maxPerHour: 1, now: fixedClock().now });
    const result = await notifier.send({ id: 'e1', email: 'e@example.com' }, { title: 'T', body: 'B', category: 'marketing' });

    assert.equal(result.reason, 'email hourly limit reached');
  });

  test('Slack thread replies and in-app security messages skip the limit', async () => {
    const log = [];
    const options = { transport: recordingTransport(log), maxPerHour: 1, now: fixedClock().now };
    const slack = createNotifier('slack', options);
    const inapp = createNotifier('inapp', options);

    await slack.send(validUsers.slack, { title: 'T', body: 'B' });
    assert.equal((await slack.send(validUsers.slack, { title: 'T', body: 'B' })).status, 'throttled');
    assert.equal((await slack.send(validUsers.slack, { title: 'T', body: 'B' }, { threadTs: '1.2' })).status, 'sent');

    await inapp.send(validUsers.inapp, { title: 'T', body: 'B' });
    assert.equal((await inapp.send(validUsers.inapp, { title: 'T', body: 'B' })).status, 'throttled');
    const security = { title: 'T', body: 'B', category: 'security' };
    await inapp.send(validUsers.inapp, security);
    assert.equal((await inapp.send(validUsers.inapp, security)).status, 'sent');
  });
});

