const { describe, test } = require('node:test');
const assert = require('node:assert/strict');
const { createNotifier, createAllNotifiers, registry } = require('./index');

const NOW = '2026-01-02T03:00:00.000Z';
const HOUR_MS = 60 * 60 * 1000;

const validUsers = {
  email: { id: 'u1', name: 'Ava', email: 'ava@example.com', emailOptIn: true },
  sms: { id: 'u2', phone: '+15551234567', smsOptIn: true },
  slack: { id: 'u3', slackId: 'U123' },
  inapp: { id: 'u4', name: 'Dee' }
};

function recordingTransport(log = []) {
  const transport = {};
  for (const channel of Object.keys(validUsers)) {
    transport[channel] = async function deliver(payload) {
      log.push({ channel, payload, receiver: this });
    };
  }
  return transport;
}

function fixedClock(iso = NOW) {
  let current = Date.parse(iso);
  return {
    now: () => new Date(current),
    advance: ms => { current += ms; }
  };
}

describe('registry and factories', () => {
  test('registry entries are factories for their channel, with or without new', () => {
    for (const [channel, factory] of Object.entries(registry)) {
      assert.equal(factory({}).channel, channel);
      assert.equal(new factory({}).channel, channel);
    }
  });

  test('createNotifier rejects inherited object keys as unknown channels', () => {
    for (const name of ['constructor', 'toString', '__proto__', 'hasOwnProperty']) {
      assert.throws(() => createNotifier(name), /unknown notification channel/);
    }
  });

  test('options.channel cannot rename a notifier', async () => {
    const log = [];
    const notifier = createNotifier('sms', { channel: 'email', transport: recordingTransport(log) });
    const result = await notifier.send(validUsers.sms, { title: 'T', body: 'B' });

    assert.equal(notifier.channel, 'sms');
    assert.equal(result.channel, 'sms');
    assert.equal(log[0].channel, 'sms');
  });

  test('createAllNotifiers shares one throttle store without mixing channels', async () => {
    const throttleStore = new Map();
    const notifiers = createAllNotifiers({ transport: recordingTransport(), throttleStore, maxPerHour: 1 });
    const message = { title: 'T', body: 'B' };

    for (const [channel, notifier] of Object.entries(notifiers)) {
      assert.equal((await notifier.send(validUsers[channel], message)).status, 'sent');
    }
    assert.deepEqual([...throttleStore.keys()].sort(), [
      'email:u1:general',
      'inapp:u4:general',
      'slack:u3:general',
      'sms:u2:general'
    ]);
  });

  test('send works when detached from the notifier object', async () => {
    const { send } = createNotifier('inapp', { transport: recordingTransport() });
    assert.equal((await send(validUsers.inapp, { title: 'T', body: 'B' })).status, 'sent');
  });
});

describe('shared validation', () => {
  // Per channel, to catch a channel check running before the shared user checks.
  const userCases = [
    ['missing user', null, /^user is required$/],
    ['non-object user', 'u1', /^user is required$/],
    ['empty user id', { id: '' }, /user\.id is required/]
  ];

  for (const channel of Object.keys(validUsers)) {
    for (const [name, user, expected] of userCases) {
      test(`${channel} rejects ${name}`, async () => {
        const notifier = createNotifier(channel, { transport: recordingTransport() });
        await assert.rejects(() => notifier.send(user, { title: 'T', body: 'B' }), { name: 'TypeError', message: expected });
      });
    }
  }

  const messageCases = [
    ['missing message', null, /^message is required$/],
    ['empty title', { title: '', body: 'B' }, /message\.title and message\.body are required/],
    ['missing body', { title: 'T' }, /message\.title and message\.body are required/]
  ];

  for (const [name, message, expected] of messageCases) {
    test(`rejects ${name}`, async () => {
      const notifier = createNotifier('sms', { transport: recordingTransport() });
      await assert.rejects(() => notifier.send(validUsers.sms, message), { name: 'TypeError', message: expected });
    });
  }

  test('channel user checks run after the shared checks', async () => {
    const checks = [
      ['email', { id: 'u1', email: 'not-an-address' }, /user\.email is required/],
      ['sms', { id: 'u2', phone: '+0123' }, /E\.164/],
      ['slack', { id: 'u3' }, /slackId or user\.slackChannel/],
      ['inapp', { id: 'u4', disabledInApp: true }, /disabled for this user/]
    ];
    for (const [channel, user, expected] of checks) {
      const notifier = createNotifier(channel, { transport: recordingTransport() });
      await assert.rejects(() => notifier.send(user, { title: 'T', body: 'B' }), { name: 'TypeError', message: expected });
      await assert.rejects(() => notifier.send({ email: 'a@b' }, { title: 'T', body: 'B' }), /user\.id is required/);
    }
  });
});

describe('throttling', () => {
  const defaultLimits = { email: 8, sms: 4, slack: 20, inapp: 50 };

  for (const [channel, limit] of Object.entries(defaultLimits)) {
    test(`${channel} allows ${limit} sends per hour by default`, async () => {
      const notifier = createNotifier(channel, { transport: recordingTransport(), now: fixedClock().now });
      const message = { title: 'T', body: 'B' };

      for (let sent = 0; sent < limit; sent++) {
        assert.equal((await notifier.send(validUsers[channel], message)).status, 'sent');
      }
      assert.equal((await notifier.send(validUsers[channel], message)).status, 'throttled');
    });
  }

